INSERT INTO public.curriculum_prerequisites (skill_code, requires_code, requires_kind, strength, reason, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'ENVI.G3.NATURA.SOIL.SOIL_TYPES', 'skill', 'essential', 'Grade 3 soil conservation activities lead into adding compost to the soil. Proposed, to confirm by a CBC Agriculture teacher.', 'proposed') ON CONFLICT (skill_code, requires_code) DO UPDATE SET requires_kind = EXCLUDED.requires_kind, strength = EXCLUDED.strength, reason = EXCLUDED.reason WHERE public.curriculum_prerequisites.status = 'proposed';
