INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS.M_AG4_CM_ANY', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS', 'Thinks any waste can go on the compost heap (polythene, tins, glass).', '{"question":"Which of these should NOT go on a compost heap?","wrong_answer":"A polythene bag","correct_answer":"Banana peelings"}'::jsonb, 'The child thinks a compost heap is a general rubbish heap.', 'Offer "A polythene bag" next to the right answer and ask the question again in a new context.', 'Dig up an old heap with a teacher. Ask what rotted and what did not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS.M_AG4_CM_MEAT', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS', 'Thinks cooked food, meat and bones are good for compost.', '{"question":"Why are meat bones and cooked food kept out of the compost heap?","wrong_answer":"They are the best food for a compost heap","correct_answer":"They draw rats and flies and smell"}'::jsonb, 'The child knows meat rots and so thinks it belongs.', 'Offer "They are the best food for a compost heap" next to the right answer and ask the question again in a new context.', 'Ask what comes to a heap with meat scraps in it, and whether the school garden needs those visitors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS.M_AG4_CM_FERT', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS', 'Calls shop fertiliser a compost material.', '{"question":"Which of these is made by rotting plant remains and dung?","wrong_answer":"Fertiliser bought from the shop","correct_answer":"Compost manure"}'::jsonb, 'The child links manure, fertiliser and compost as one thing.', 'Offer "Fertiliser bought from the shop" next to the right answer and ask the question again in a new context.', 'Show a bag of fertiliser and a handful of compost. Ask where each one comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING.M_AG4_CK_ONE', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'Heaps one kind of material only (all dry sticks or all wet peelings).', '{"question":"What makes the best compost heap?","wrong_answer":"Dry and fresh materials mixed in layers","correct_answer":"Only wet peelings pressed into one heap"}'::jsonb, 'The child thinks more of one good thing is better.', 'Offer "Dry and fresh materials mixed in layers" next to the right answer and ask the question again in a new context.', 'Make two small heaps, one with one material and one with a mix. Compare them after a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING.M_AG4_CK_DRY', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'Leaves the heap dry and open, or soaks it with water.', '{"question":"What does a compost heap need while it rots?","wrong_answer":"To be kept dry and open to the sun","correct_answer":"To be kept damp and covered"}'::jsonb, 'The child thinks rotting happens by itself.', 'Offer "To be kept dry and open to the sun" next to the right answer and ask the question again in a new context.', 'Compare a damp covered heap and a dry open heap after a month. Then flood one and smell it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING.M_AG4_CK_EARLY', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'Uses the compost before it has rotted.', '{"question":"When is compost ready to put on the garden?","wrong_answer":"After one day, when the heap is made","correct_answer":"When it is dark, crumbly and smells like soil"}'::jsonb, 'The child thinks compost is ready as soon as it is made.', 'Offer "After one day, when the heap is made" next to the right answer and ask the question again in a new context.', 'Open a young heap and an old heap side by side. Ask which still looks like peelings.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS.M_AG4_CM_DISEASED', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MATERIALS', 'Puts diseased plants and weeds full of seed on the compost heap.', '{"question":"Which of these should stay off the compost heap?","wrong_answer":"Dry maize stalks","correct_answer":"Weeds with ripe seeds"}'::jsonb, 'The child thinks all plant material is the same once it rots and does not know seeds and disease can live through a cool heap.', 'Offer "Dry maize stalks" next to the right answer and ask the question again in a new context.', 'Show a weed head shedding seed; ask where the seeds go if it is put on the heap and the compost is spread on the garden.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING.M_AG4_CK_LAYERS', 'AGRI.G4.CONSER.SOIL_CONSERVATION.COMPOST_MAKING', 'Thinks the materials are simply thrown in a pile with no layers and no soil or manure between them.', '{"question":"How are compost materials put on the heap?","wrong_answer":"Thrown in one pile any way","correct_answer":"In layers: dry material, green material, manure or soil, then water"}'::jsonb, 'The child has seen rubbish heaps grow by dumping and thinks a compost heap grows the same way.', 'Offer "Thrown in one pile any way" next to the right answer and ask the question again in a new context.', 'Build a model heap in a clear bottle with coloured layers: dry, green, soil, then sprinkle water; compare it with a jumbled bottle after two weeks.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING.M_AG4_DM_FAST', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING', 'Thinks drip irrigation pours water out quickly like a hosepipe.', '{"question":"How does drip irrigation give water to a plant?","wrong_answer":"It pours a lot of water out very fast","correct_answer":"It gives water slowly, drop by drop"}'::jsonb, 'The child thinks of a tap or hosepipe, not of a drip.', 'Offer "It pours a lot of water out very fast" next to the right answer and ask the question again in a new context.', 'Pierce a bottle with a pin hole and watch it. Ask how fast the water comes out.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING.M_AG4_DM_LEAVES', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING', 'Thinks the drip falls on the leaves of the plant.', '{"question":"Where does the water from a drip system go?","wrong_answer":"Onto the leaves of the plant","correct_answer":"Into the soil at the roots"}'::jsonb, 'The child thinks of rain falling on the plant.', 'Offer "Onto the leaves of the plant" next to the right answer and ask the question again in a new context.', 'Ask which part of the plant takes up water. Look at where a real drip tube ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING.M_AG4_DM_WASTE', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING', 'Thinks drip irrigation uses more water than a watering can.', '{"question":"Why does drip irrigation save water?","wrong_answer":"It uses more water so the plant grows faster","correct_answer":"Little water is lost and it goes to the roots"}'::jsonb, 'The child thinks slow means more.', 'Offer "It uses more water so the plant grows faster" next to the right answer and ask the question again in a new context.', 'Water one bed with a bucket and one by drip. Measure the water used.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP.M_AG4_DS_LOW', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP', 'Puts the water container lower than the plants.', '{"question":"Where should the water container of a simple drip system be put?","wrong_answer":"Lower than the bed, on the ground","correct_answer":"Higher than the bed, on a stand"}'::jsonb, 'The child does not think about water running downhill.', 'Offer "Lower than the bed, on the ground" next to the right answer and ask the question again in a new context.', 'Raise and lower a bottle with a hole above a bed. Watch when the water flows.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP.M_AG4_DS_BIGHOLE', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP', 'Makes a big hole so the water comes out faster.', '{"question":"How big should the hole in a drip bottle be?","wrong_answer":"Big, so all the water comes out at once","correct_answer":"Tiny, so the water comes out drop by drop"}'::jsonb, 'The child thinks speed helps the plant.', 'Offer "Big, so all the water comes out at once" next to the right answer and ask the question again in a new context.', 'Make one tiny hole and one large hole in two bottles. Watch which waters a whole week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP.M_AG4_DS_FAR', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP', 'Puts the drip far from the plant roots.', '{"question":"Where should the end of the drip tube be placed?","wrong_answer":"Far from the plant, in the middle of the path","correct_answer":"Next to the plant roots"}'::jsonb, 'The child does not link the drip to where the roots take water.', 'Offer "Far from the plant, in the middle of the path" next to the right answer and ask the question again in a new context.', 'Dig up a small plant and show how close its roots are to the stem.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING.M_AG4_DM_WHENEVER', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_MEANING', 'Thinks drip irrigation means watering only when it rains a little.', '{"question":"What is drip irrigation?","wrong_answer":"Watering when it drizzles","correct_answer":"Water dripping slowly to the roots from a pipe or container"}'::jsonb, 'The word "drip" reminds the child of light rain.', 'Offer "Watering when it drizzles" next to the right answer and ask the question again in a new context.', 'Show the bottle dripping beside a plant on a dry day; ask where the water comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP.M_AG4_DS_NOCHECK', 'AGRI.G4.CONSER.WATER_CONSERVATION.DRIP_SETUP', 'Thinks a drip system, once set up, needs no checking or refilling.', '{"question":"A bottle drip has been set up. What must you keep doing?","wrong_answer":"Nothing, it works by itself","correct_answer":"Refill it and check the hole is not blocked"}'::jsonb, 'The child thinks setting up is the whole job, as with planting.', 'Offer "Nothing, it works by itself" next to the right answer and ask the question again in a new context.', 'Leave one bottle unchecked for a week in class; it runs dry or the hole clogs with soil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES.M_AG4_FT_PETROL', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES', 'Thinks petrol or diesel is used as a cooking fuel at home.', '{"question":"Which of these is a fuel used for cooking at home?","wrong_answer":"Petrol","correct_answer":"Cooking gas"}'::jsonb, 'The child knows petrol is a fuel and does not know it is for engines.', 'Offer "Petrol" next to the right answer and ask the question again in a new context.', 'Ask what burns in a jiko, a gas cooker and a car. Talk about why petrol is dangerous indoors.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES.M_AG4_FT_ONE', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES', 'Thinks firewood is the only fuel at home.', '{"question":"Which list names only fuels used at home?","wrong_answer":"Firewood, charcoal, paraffin and gas","correct_answer":"Firewood only, every home uses the same"}'::jsonb, 'The child sees only the fuel used in their own home.', 'Offer "Firewood, charcoal, paraffin and gas" next to the right answer and ask the question again in a new context.', 'Ask each learner which fuels their home uses and make one class list.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES.M_AG4_FT_STATE', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES', 'Mixes up solid, liquid and gas fuels.', '{"question":"Which of these is a liquid fuel?","wrong_answer":"Charcoal","correct_answer":"Paraffin"}'::jsonb, 'The child links fuel names to the fire, not to the form of the fuel.', 'Offer "Charcoal" next to the right answer and ask the question again in a new context.', 'Pour paraffin, hold charcoal and ask how each can be carried and stored.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING.M_AG4_FS_OPENLID', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING', 'Cooks with the lid off the pot.', '{"question":"Which habit saves fuel when boiling beans?","wrong_answer":"Cooking with the lid off so you can watch","correct_answer":"Cooking with a lid on the pot"}'::jsonb, 'The child wants to watch the food and does not think the heat escapes.', 'Offer "Cooking with the lid off so you can watch" next to the right answer and ask the question again in a new context.', 'Boil two pots of water, one with a lid and one without, and time them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING.M_AG4_FS_BIG', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING', 'Thinks a big flame cooks food faster and so is better.', '{"question":"The pot is boiling. What should the cook do to save fuel?","wrong_answer":"Add more wood so the flame is big","correct_answer":"Make the fire small to keep it simmering"}'::jsonb, 'The child thinks more fire means more cooking.', 'Offer "Add more wood so the flame is big" next to the right answer and ask the question again in a new context.', 'Ask whether the water gets hotter than boiling when the flame is bigger.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING.M_AG4_FS_WET', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING', 'Thinks wet firewood is as good as dry firewood.', '{"question":"Which firewood saves the most fuel?","wrong_answer":"Wet, freshly cut wood","correct_answer":"Dry wood"}'::jsonb, 'The child thinks all wood burns the same.', 'Offer "Wet, freshly cut wood" next to the right answer and ask the question again in a new context.', 'Try to light a dry stick and a wet one and compare smoke and heat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES.M_AG4_FT_ELECTRIC', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_TYPES', 'Thinks electricity is not a fuel used for cooking because you cannot see it burn.', '{"question":"Which of these is used for cooking in some homes?","wrong_answer":"Only things that burn with a flame","correct_answer":"Electricity, as well as firewood, charcoal, paraffin and gas"}'::jsonb, 'The child thinks a fuel must be something that burns with a flame.', 'Offer "Only things that burn with a flame" next to the right answer and ask the question again in a new context.', 'Show a picture of an electric cooker and ask what makes it hot.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING.M_AG4_FS_SOAK', 'AGRI.G4.CONSER.FUEL_CONSERVATION.FUEL_SAVING', 'Puts dry beans straight on the fire without soaking them first.', '{"question":"How can you use less fuel to cook dry beans?","wrong_answer":"Cook them dry straight away","correct_answer":"Soak them first so they cook faster"}'::jsonb, 'The child does not link a shorter cooking time with less fuel.', 'Offer "Cook them dry straight away" next to the right answer and ask the question again in a new context.', 'Compare a soaked and a dry bean: press both, then count how long each takes to cook in the demonstration.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS.M_AG4_SP_BIG', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS', 'Thinks only big animals harm crops.', '{"question":"Which of these small animals can harm a maize field?","wrong_answer":"None, only big animals harm crops","correct_answer":"Birds, rats and squirrels"}'::jsonb, 'The child thinks of elephants and baboons in the news.', 'Offer "None, only big animals harm crops" next to the right answer and ask the question again in a new context.', 'Walk the school plot and look for signs: pecked grain, tunnels, gnawed cobs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS.M_AG4_SP_BEE', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS', 'Thinks bees and butterflies harm crops.', '{"question":"Which small animal does NOT harm the crop?","wrong_answer":"A rat in the maize","correct_answer":"A bee on the bean flower"}'::jsonb, 'The child thinks every small animal on a crop is a pest.', 'Offer "A rat in the maize" next to the right answer and ask the question again in a new context.', 'Watch bees on a flowering crop. Ask what happens to the flower afterwards.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS.M_AG4_SP_MATCH', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS', 'Links an animal to the wrong damage (moles eating leaves, birds digging roots).', '{"question":"Which animal digs up roots and tubers under the ground?","wrong_answer":"A weaver bird","correct_answer":"A mole"}'::jsonb, 'The child knows the animal is a pest but not what it eats.', 'Offer "A weaver bird" next to the right answer and ask the question again in a new context.', 'Match pictures of the animals to pictures of the damage.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE.M_AG4_SC_FIXED', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE', 'Thinks a scarecrow can stay in one place all season.', '{"question":"Why is a scarecrow moved from place to place?","wrong_answer":"It does not need to be moved at all","correct_answer":"Animals get used to it if it never moves"}'::jsonb, 'The child thinks it scares by being there.', 'Offer "It does not need to be moved at all" next to the right answer and ask the question again in a new context.', 'Ask what a bird does after a week of seeing the same scarecrow that never moves.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE.M_AG4_SC_KILL', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE', 'Thinks a scarecrow, or poison and traps, should kill the animals.', '{"question":"What is a scarecrow made to do?","wrong_answer":"Kill the animals that come near","correct_answer":"Scare the animals away without hurting them"}'::jsonb, 'The child thinks protecting crops means killing pests.', 'Offer "Kill the animals that come near" next to the right answer and ask the question again in a new context.', 'Ask who also visits the plot, such as bees, and what poison would do to them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE.M_AG4_SC_HIDDEN', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE', 'Hides the scarecrow at the edge of the crop.', '{"question":"Where is the best place to stand a scarecrow?","wrong_answer":"Hidden in the bush at the edge","correct_answer":"In the middle of the crop, where it can be seen"}'::jsonb, 'The child thinks it should be a surprise.', 'Offer "Hidden in the bush at the edge" next to the right answer and ask the question again in a new context.', 'Stand a scarecrow at the edge and in the middle and ask which one the bird can see from the sky.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS.M_AG4_SP_DOMESTIC', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SMALL_PESTS', 'Counts goats and chickens that wander into the garden as wild animals.', '{"question":"Which of these is a small wild animal that destroys crops?","wrong_answer":"A neighbour''s goat","correct_answer":"A mole rat"}'::jsonb, 'The child sorts by the damage done, not by whether people keep the animal.', 'Offer "A neighbour''s goat" next to the right answer and ask the question again in a new context.', 'Ask who owns the goat and who feeds it; then ask who owns the mole rat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE.M_AG4_SC_DULL', 'AGRI.G4.CONSER.CONSERVING_WILD_ANIMALS.SCARECROW_MAKE', 'Makes the scarecrow from dull, stiff material that does not move or rustle.', '{"question":"Which scarecrow scares birds better?","wrong_answer":"A stiff one made of dull sacks","correct_answer":"One with bright, loose cloth and tins that move and rattle in the wind"}'::jsonb, 'The child thinks a human shape alone frightens the birds.', 'Offer "A stiff one made of dull sacks" next to the right answer and ask the question again in a new context.', 'Hang a still sack and a flapping bright cloth; ask the class which they notice first from far away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS.M_AG4_TS_BIGSEED', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS', 'Thinks maize and beans have tiny seeds.', '{"question":"Which crop has a large seed, not a tiny one?","wrong_answer":"Carrot","correct_answer":"Maize"}'::jsonb, 'The child links "seed" to any crop sown from seed.', 'Offer "Carrot" next to the right answer and ask the question again in a new context.', 'Put a maize seed, a bean and a carrot seed in the hand and compare them.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS.M_AG4_TS_NURSERY', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS', 'Thinks cabbage and tomato are sown straight in the plot like carrot.', '{"question":"Which crop is usually started in a nursery and moved later?","wrong_answer":"Carrot","correct_answer":"Cabbage"}'::jsonb, 'The child thinks all tiny seeds are treated the same.', 'Offer "Carrot" next to the right answer and ask the question again in a new context.', 'Ask a farmer how he starts carrots and how he starts tomatoes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS.M_AG4_TS_CUTTING', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS', 'Thinks crops grown from cuttings, such as sweet potato vines, are sown from tiny seeds.', '{"question":"How is a sweet potato crop usually planted?","wrong_answer":"By sowing tiny seeds","correct_answer":"By planting pieces of vine"}'::jsonb, 'The child thinks every crop starts from seed.', 'Offer "By sowing tiny seeds" next to the right answer and ask the question again in a new context.', 'Show a sweet potato vine cutting next to a packet of carrot seed.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING.M_AG4_SB_COARSE', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING', 'Thinks lumps and stones in the seedbed do not matter.', '{"question":"How should the soil of a seedbed for tiny seeds be?","wrong_answer":"Rough, with lumps and stones","correct_answer":"Fine, like flour"}'::jsonb, 'The child thinks seeds will find their way.', 'Offer "Rough, with lumps and stones" next to the right answer and ask the question again in a new context.', 'Sow tiny seeds in a lumpy bed and a fine bed and compare how many come up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING.M_AG4_SB_DEEP', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING', 'Sows tiny seeds deep.', '{"question":"How deep are tiny seeds sown?","wrong_answer":"Deep, about as deep as a hand","correct_answer":"Very shallow, and covered lightly"}'::jsonb, 'The child thinks deep soil protects the seeds.', 'Offer "Deep, about as deep as a hand" next to the right answer and ask the question again in a new context.', 'Sow seeds at two depths and see which come up. A tiny seed has little food to push up.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING.M_AG4_SB_THICK', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING', 'Sows thickly and never thins the seedlings.', '{"question":"What should be done when carrot seedlings come up crowded?","wrong_answer":"Leave them all, more plants give more carrots","correct_answer":"Thin them so each has room"}'::jsonb, 'The child thinks more plants means more crop.', 'Offer "Leave them all, more plants give more carrots" next to the right answer and ask the question again in a new context.', 'Grow one thick row and one thinned row. Compare the carrots at harvest.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS.M_AG4_TS_NAME', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.TINY_SEED_CROPS', 'Names spinach or sukuma wiki as sown from tiny seeds straight in the plot when the class grew it from seedlings.', '{"question":"Which crop is sown straight into the plot from tiny seeds?","wrong_answer":"Sukuma wiki, from transplanted seedlings","correct_answer":"Carrot"}'::jsonb, 'The child names a crop with small seeds without asking how it is usually planted.', 'Offer "Sukuma wiki, from transplanted seedlings" next to the right answer and ask the question again in a new context.', 'Show a carrot: ask whether a carrot root could be moved without breaking it. Root crops are sown where they grow.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING.M_AG4_SB_WATERHARD', 'AGRI.G4.FOOD_P.DIRECT_SOWING_OF_TINY_SE.SEEDBED_SOWING', 'Pours water hard from a bucket on newly sown tiny seeds.', '{"question":"How should a bed of tiny seeds be watered after sowing?","wrong_answer":"Pour a bucket over it quickly","correct_answer":"Gently, with a watering can with a fine rose"}'::jsonb, 'The child thinks more water at once is better and does not picture the seeds washing away.', 'Offer "Pour a bucket over it quickly" next to the right answer and ask the question again in a new context.', 'Sow sand-coloured seeds in a tray and pour water hard: watch them wash to one corner.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES.M_AG4_FY_ANYWHERE', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES', 'Thinks any fruit grows well anywhere.', '{"question":"Which fruit does best at the hot coast?","wrong_answer":"Apple","correct_answer":"Mango"}'::jsonb, 'The child sees all fruits for sale in the market and does not know where they come from.', 'Offer "Apple" next to the right answer and ask the question again in a new context.', 'Ask which fruits grow near the school and which come from far.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES.M_AG4_FY_TREE', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES', 'Thinks fruits grow only on tall trees.', '{"question":"Which of these gives a fruit but is not a tall tree?","wrong_answer":"None, all fruits come from tall trees","correct_answer":"Banana and pawpaw plants"}'::jsonb, 'The child pictures a mango tree for every fruit.', 'Offer "None, all fruits come from tall trees" next to the right answer and ask the question again in a new context.', 'Look at a banana plant and a passion fruit vine and ask where the fruit hangs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES.M_AG4_FY_ROOT', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES', 'Calls a root crop a fruit.', '{"question":"Which of these is NOT a fruit crop?","wrong_answer":"Cassava","correct_answer":"Guava"}'::jsonb, 'The child thinks all sweet or eaten crops are fruits.', 'Offer "Cassava" next to the right answer and ask the question again in a new context.', 'Dig up a cassava plant and ask which part we eat.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING.M_AG4_FG_DEEP', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING', 'Plants the seedling deeper than it grew, or buries the stem.', '{"question":"How deep should a fruit seedling be planted?","wrong_answer":"Deep, with the stem buried","correct_answer":"At the same depth it grew in the bag"}'::jsonb, 'The child thinks deeper is safer.', 'Offer "Deep, with the stem buried" next to the right answer and ask the question again in a new context.', 'Show the soil mark on the stem of a seedling.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING.M_AG4_FG_NOMANURE', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING', 'Plants in plain hard soil with no manure.', '{"question":"What is mixed with the topsoil in the planting hole?","wrong_answer":"Stones and sand only","correct_answer":"Manure or compost"}'::jsonb, 'The child thinks a hole is only a place to stand the plant.', 'Offer "Stones and sand only" next to the right answer and ask the question again in a new context.', 'Plant two seedlings, one with manure and one without, and compare after a month.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING.M_AG4_FG_CROWD', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING', 'Plants seedlings close together to save space.', '{"question":"How far apart should mango seedlings be planted?","wrong_answer":"As close as possible to save space","correct_answer":"Far enough apart for each tree to grow wide"}'::jsonb, 'The child thinks of the small seedling and not the big tree.', 'Offer "As close as possible to save space" next to the right answer and ask the question again in a new context.', 'Show how wide a mature mango tree is.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING.M_AG4_FG_DRYSTOP', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_GROWING', 'Stops watering after the first day.', '{"question":"How is a young fruit seedling looked after in dry weather?","wrong_answer":"Water once on the day it is planted, then stop","correct_answer":"Water it regularly and keep a mulch around it"}'::jsonb, 'The child thinks planting finishes the job.', 'Offer "Water once on the day it is planted, then stop" next to the right answer and ask the question again in a new context.', 'Ask what happens to a seedling that dries out for a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES.M_AG4_FY_VEG', 'AGRI.G4.FOOD_P.GROWING_FRUITS.FRUIT_TYPES', 'Calls tomato, pumpkin and avocado vegetables, so leaves them out of a list of fruits.', '{"question":"Is an avocado a fruit?","wrong_answer":"No, it is a vegetable because it is not sweet","correct_answer":"Yes, it is a fruit: it grows from the flower and holds the seed"}'::jsonb, 'The child sorts by taste (sweet = fruit) and by how food is eaten at home.', 'Offer "No, it is a vegetable because it is not sweet" next to the right answer and ask the question again in a new context.', 'Cut an avocado and a tomato: point at the seeds inside. A fruit holds the seeds.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES.M_AG4_AT_WILD', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES', 'Calls a wild animal domestic because it is seen near homes.', '{"question":"Which of these is a domestic animal?","wrong_answer":"A zebra","correct_answer":"A goat"}'::jsonb, 'The child thinks any animal near people is domestic.', 'Offer "A zebra" next to the right answer and ask the question again in a new context.', 'Ask who feeds, houses and looks after each animal.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES.M_AG4_AT_FOUR', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES', 'Thinks only four-legged animals are domestic animals (leaves out chickens and bees).', '{"question":"Which of these is a domestic animal kept for eggs?","wrong_answer":"None, birds are not domestic animals","correct_answer":"A chicken"}'::jsonb, 'The child pictures a cow or a goat as an animal.', 'Offer "None, birds are not domestic animals" next to the right answer and ask the question again in a new context.', 'Ask which birds the community keeps at home.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES.M_AG4_AT_GROUP', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES', 'Puts an animal in the wrong group (a goat in poultry, a duck in livestock).', '{"question":"Which of these is poultry?","wrong_answer":"A goat","correct_answer":"A duck"}'::jsonb, 'The child sorts by size and noise.', 'Offer "A goat" next to the right answer and ask the question again in a new context.', 'Ask which animals have feathers and lay eggs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG4_AU_MIX', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Gives an animal the wrong product (eggs from cows, wool from goats).', '{"question":"Which animal gives us wool?","wrong_answer":"A goat","correct_answer":"A sheep"}'::jsonb, 'The child knows the product but not which animal gives it.', 'Offer "A goat" next to the right answer and ask the question again in a new context.', 'Show wool, milk, eggs and honey and ask where each comes from.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG4_AU_ONE', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks an animal gives only one thing.', '{"question":"Which animal gives us milk, meat and hides?","wrong_answer":"None, an animal gives only one thing","correct_answer":"A cow"}'::jsonb, 'The child learns one animal with one use.', 'Offer "None, an animal gives only one thing" next to the right answer and ask the question again in a new context.', 'Make a list of everything one cow gives the family.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG4_AU_WORK', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks any animal can pull a plough or carry a load.', '{"question":"Which animal is used to carry loads?","wrong_answer":"A hen","correct_answer":"A donkey"}'::jsonb, 'The child thinks all animals can work.', 'Offer "A hen" next to the right answer and ask the question again in a new context.', 'Ask which animals in the village pull carts and which do not.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES.M_AG4_AT_PET', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_TYPES', 'Thinks cats and dogs are not domestic animals because they are not eaten.', '{"question":"Is a dog a domestic animal?","wrong_answer":"No, we do not eat it","correct_answer":"Yes, people keep it at home"}'::jsonb, 'The child links domestic animals only with food animals.', 'Offer "No, we do not eat it" next to the right answer and ask the question again in a new context.', 'Ask who feeds and shelters the dog. Domestic means kept and cared for by people.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES.M_AG4_AU_DOG', 'AGRI.G4.FOOD_P.USES_OF_DOMESTIC_ANIMALS.ANIMAL_USES', 'Thinks dogs and cats are kept for no use.', '{"question":"What use is a cat on a farm?","wrong_answer":"None, it is only a pet","correct_answer":"It catches rats and mice"}'::jsonb, 'The child does not see guarding or catching pests as a use.', 'Offer "None, it is only a pet" next to the right answer and ask the question again in a new context.', 'Ask what eats the maize in a store at night, and what chases it away.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE.M_AG4_MI_FILL', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE', 'Thinks a meal is good if it fills the stomach.', '{"question":"What makes a meal balanced?","wrong_answer":"It is big enough to fill the stomach","correct_answer":"It has foods from all the groups"}'::jsonb, 'The child links good food with being full.', 'Offer "It is big enough to fill the stomach" next to the right answer and ask the question again in a new context.', 'Compare a large plate of ugali alone with a smaller plate of ugali, beans and greens.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE.M_AG4_MI_ONE', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE', 'Thinks one food, such as ugali, gives the body everything.', '{"question":"Why can a child not live on ugali alone?","wrong_answer":"Ugali gives everything the body needs","correct_answer":"It does not give all the things the body needs"}'::jsonb, 'The child eats one staple most days.', 'Offer "Ugali gives everything the body needs" next to the right answer and ask the question again in a new context.', 'Ask what happens to a child who eats only one food for months.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE.M_AG4_MI_COST', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE', 'Thinks a balanced meal needs expensive food.', '{"question":"Which family can eat a balanced meal?","wrong_answer":"Only a rich family that can buy meat","correct_answer":"Any family that mixes foods from all groups"}'::jsonb, 'The child links balance with money.', 'Offer "Only a rich family that can buy meat" next to the right answer and ask the question again in a new context.', 'Make a cheap balanced meal with ugali, ndengu and managu.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT.M_AG4_GS_UGALI', 'AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT', 'Puts ugali or rice with the body-building foods because they fill you.', '{"question":"Ugali gives mainly what?","wrong_answer":"Body building","correct_answer":"Energy"}'::jsonb, 'The child thinks filling food builds the body.', 'Offer "Body building" next to the right answer and ask the question again in a new context.', 'Ask what a runner eats before a race and why.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT.M_AG4_GS_MEAT', 'AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT', 'Puts meat, eggs and beans with the energy foods.', '{"question":"Eggs, fish and beans help the body to do what mainly?","wrong_answer":"Give energy","correct_answer":"Build and repair the body"}'::jsonb, 'The child thinks all food that fills gives energy.', 'Offer "Give energy" next to the right answer and ask the question again in a new context.', 'Ask which foods a growing child or someone with a wound needs.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT.M_AG4_GS_FRUIT', 'AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT', 'Puts fruits and vegetables with the body-building foods.', '{"question":"Sukuma wiki and mangoes are which kind of food?","wrong_answer":"Body-building","correct_answer":"Protective"}'::jsonb, 'The child thinks anything that is good for you builds the body.', 'Offer "Body-building" next to the right answer and ask the question again in a new context.', 'Ask what protective means and which colours protect the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK.M_AG4_MP_ONE', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK', 'Picks a plate with only one group, such as ugali, rice and chapati.', '{"question":"Which plate is a balanced meal?","wrong_answer":"Ugali, rice and chapati","correct_answer":"Ugali, beans and sukuma wiki"}'::jsonb, 'The child counts the number of foods, not the groups.', 'Offer "Ugali, rice and chapati" next to the right answer and ask the question again in a new context.', 'Sort each food on the plate into a group. Count the groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK.M_AG4_MP_NOVEG', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK', 'Leaves out vegetables or fruit and calls the meal balanced.', '{"question":"A child eats ugali and fish. What is missing?","wrong_answer":"Nothing is missing","correct_answer":"A protective food such as sukuma wiki"}'::jsonb, 'The child does not count vegetables as part of the meal.', 'Offer "Nothing is missing" next to the right answer and ask the question again in a new context.', 'Ask which group each food is in and which group is empty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK.M_AG4_MP_SWEET', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK', 'Thinks soda, sweets or biscuits complete a meal.', '{"question":"Which one makes a meal more balanced?","wrong_answer":"A bottle of soda","correct_answer":"A fruit"}'::jsonb, 'The child thinks anything extra is good.', 'Offer "A bottle of soda" next to the right answer and ask the question again in a new context.', 'Look at what a soda gives: sugar and no body-building or protective foods.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE.M_AG4_MI_MORE', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_IMPORTANCE', 'Thinks eating a lot makes a meal balanced.', '{"question":"What makes a meal balanced?","wrong_answer":"A very big plate of food","correct_answer":"Foods from all the food groups in the right amounts"}'::jsonb, 'The child links "balanced" with plenty.', 'Offer "A very big plate of food" next to the right answer and ask the question again in a new context.', 'Show a big plate of only rice next to a smaller plate of rice, beans and cabbage; ask which has all three groups.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT.M_AG4_GS_MILK', 'AGRI.G4.FOOD_P.BALANCED_MEAL.GROUPS_SORT', 'Puts milk with the drinks that give energy, not with the body-building foods.', '{"question":"Which group is milk in?","wrong_answer":"Energy-giving foods","correct_answer":"Body-building foods"}'::jsonb, 'The child thinks of milk as a drink like tea or soda.', 'Offer "Energy-giving foods" next to the right answer and ask the question again in a new context.', 'Ask what young animals and babies grow on; milk builds the body.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK.M_AG4_MP_TWO', 'AGRI.G4.FOOD_P.BALANCED_MEAL.MEAL_PICK', 'Picks a plate with two groups, such as ugali and beans, and calls it balanced.', '{"question":"Which meal is balanced?","wrong_answer":"Ugali and beans","correct_answer":"Ugali, beans and sukuma wiki"}'::jsonb, 'The child checks for energy and body-building foods and forgets protective foods.', 'Offer "Ugali and beans" next to the right answer and ask the question again in a new context.', 'Tick the groups on a plate chart: energy, body-building, protective. One box stays empty.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG4_CMT_STEAM', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks steaming means the food sits in the water.', '{"question":"In steaming, where is the food?","wrong_answer":"Inside the boiling water","correct_answer":"Above the water, cooked by the steam"}'::jsonb, 'The child mixes boiling and steaming.', 'Offer "Inside the boiling water" next to the right answer and ask the question again in a new context.', 'Show a steamer with the food on a rack above the water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG4_CMT_FRY', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks shallow frying uses no oil, or uses a deep pot of oil.', '{"question":"What is used in shallow frying?","wrong_answer":"A pot full of oil to cover the food","correct_answer":"A little oil in a pan"}'::jsonb, 'The child mixes shallow and deep frying.', 'Offer "A pot full of oil to cover the food" next to the right answer and ask the question again in a new context.', 'Show a frying pan with a spoonful of oil beside a pot full of oil.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG4_CMT_ROAST', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks roasting is cooking in water.', '{"question":"How is a maize cob roasted?","wrong_answer":"In a pot of boiling water","correct_answer":"Over a fire or in an oven, with dry heat"}'::jsonb, 'The child links all cooking with a pot of water.', 'Offer "In a pot of boiling water" next to the right answer and ask the question again in a new context.', 'Roast a cob over a jiko and compare it with a boiled cob.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT.M_AG4_CS_FRYALL', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT', 'Thinks every food is best fried.', '{"question":"Which method suits dry beans best?","wrong_answer":"Shallow frying","correct_answer":"Boiling"}'::jsonb, 'The child likes fried food and thinks frying cooks everything.', 'Offer "Shallow frying" next to the right answer and ask the question again in a new context.', 'Try to fry dry beans and ask why they stay hard.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT.M_AG4_CS_OVER', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT', 'Cooks green vegetables for a long time.', '{"question":"How long should sukuma wiki be cooked?","wrong_answer":"For a very long time until it is soft and brown","correct_answer":"For a short time, until it is just soft and still green"}'::jsonb, 'The child thinks longer cooking makes food safer.', 'Offer "For a very long time until it is soft and brown" next to the right answer and ask the question again in a new context.', 'Cook greens for 3 minutes and for 30 minutes and compare colour and taste.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT.M_AG4_CS_SHORT', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT', 'Thinks hard foods such as beans cook as fast as soft foods.', '{"question":"Which food needs the longest time to cook?","wrong_answer":"Spinach","correct_answer":"Dry beans"}'::jsonb, 'The child does not tell hard foods from soft foods.', 'Offer "Spinach" next to the right answer and ask the question again in a new context.', 'Put beans and spinach in two pots and see which is soft first.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE.M_AG4_CF_HANDLE', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE', 'Leaves the pot handle sticking out over the edge of the stove.', '{"question":"How should the handle of a pot on the stove be turned?","wrong_answer":"Sticking out, so it is easy to reach","correct_answer":"Turned inwards, away from the edge"}'::jsonb, 'The child thinks of reaching, not of knocking.', 'Offer "Sticking out, so it is easy to reach" next to the right answer and ask the question again in a new context.', 'Ask what happens when a child passes and brushes the handle.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE.M_AG4_CF_WATERFIRE', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE', 'Throws water on an oil fire.', '{"question":"The oil in a pan catches fire. What should be done?","wrong_answer":"Pour water on it","correct_answer":"Cover it with a lid and call a grown-up"}'::jsonb, 'The child thinks water puts out every fire.', 'Offer "Pour water on it" next to the right answer and ask the question again in a new context.', 'Talk about why water makes burning oil splash and spread.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE.M_AG4_CF_LEAVE', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE', 'Leaves a pot or a fire alone while cooking.', '{"question":"The pot is on the fire. What should the cook do?","wrong_answer":"Go out and play, it will be fine","correct_answer":"Stay near and watch the pot"}'::jsonb, 'The child thinks cooking needs no watching.', 'Offer "Go out and play, it will be fine" next to the right answer and ask the question again in a new context.', 'Ask what can happen to a pot that boils dry or a fire that spreads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS.M_AG4_CMT_BOIL', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_METHODS', 'Thinks boiling means only heating water, not cooking food in it.', '{"question":"Which is cooked by boiling?","wrong_answer":"Nothing, boiling is only for water","correct_answer":"Eggs, potatoes or rice cooked in boiling water"}'::jsonb, 'The child has seen water boiled for tea and drinking and links the word only with water.', 'Offer "Nothing, boiling is only for water" next to the right answer and ask the question again in a new context.', 'Show an egg going into a pan of boiling water and coming out cooked.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT.M_AG4_CS_NOSALT', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SUIT', 'Thinks the method does not matter as long as the food is hot.', '{"question":"Why cook sukuma wiki quickly instead of boiling it for an hour?","wrong_answer":"It makes no difference","correct_answer":"Long cooking destroys its goodness and spoils the taste and colour"}'::jsonb, 'The child judges cooking only by whether food is hot and soft.', 'Offer "It makes no difference" next to the right answer and ask the question again in a new context.', 'Compare bright green quickly cooked sukuma with grey overcooked sukuma; ask which looks and tastes better.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE.M_AG4_CF_DIRTY', 'AGRI.G4.FOOD_P.COOKING_FOOD.COOKING_SAFE', 'Thinks the kitchen can be cleaned the next day.', '{"question":"When should the pots and surfaces be cleaned after cooking?","wrong_answer":"The next day","correct_answer":"Straight after cooking and eating"}'::jsonb, 'The child does not link leftover food with flies and germs.', 'Offer "The next day" next to the right answer and ask the question again in a new context.', 'Leave a crumb of food on a plate overnight in a jar; look at the flies or mould the next day.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES.M_AG4_HP_PERFUME', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES', 'Thinks perfume or oil takes the place of washing.', '{"question":"Which keeps the body clean?","wrong_answer":"Putting on perfume","correct_answer":"Bathing with soap and water"}'::jsonb, 'The child thinks smelling nice means clean.', 'Offer "Putting on perfume" next to the right answer and ask the question again in a new context.', 'Ask whether perfume washes dirt and germs off the skin.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES.M_AG4_HP_RARE', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES', 'Thinks bathing or brushing teeth once a week is enough.', '{"question":"How often should teeth be brushed?","wrong_answer":"Once a week","correct_answer":"In the morning and at night"}'::jsonb, 'The child thinks cleaning is only for special days.', 'Offer "Once a week" next to the right answer and ask the question again in a new context.', 'Look at how quickly a smooth tooth feels rough again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES.M_AG4_HP_HANDS', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES', 'Thinks hands that look clean are clean.', '{"question":"Why must hands that look clean still be washed before eating?","wrong_answer":"Hands that look clean cannot have germs","correct_answer":"Germs are too small to see"}'::jsonb, 'The child trusts the eye.', 'Offer "Hands that look clean cannot have germs" next to the right answer and ask the question again in a new context.', 'Rub clean-looking hands in glitter or powder and see how it spreads.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING.M_AG4_HW_NOSOAP', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING', 'Thinks a rinse in water is enough.', '{"question":"What do we use to wash hands properly?","wrong_answer":"Water only","correct_answer":"Soap and clean water"}'::jsonb, 'The child thinks water removes everything.', 'Offer "Water only" next to the right answer and ask the question again in a new context.', 'Wash greasy hands with water only and then with soap.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING.M_AG4_HW_QUICK', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING', 'Dips the hands in and takes them out at once.', '{"question":"How long should hands be rubbed with soap?","wrong_answer":"One second, a quick dip is enough","correct_answer":"As long as it takes to sing a short song"}'::jsonb, 'The child thinks speed is cleanliness.', 'Offer "One second, a quick dip is enough" next to the right answer and ask the question again in a new context.', 'Count while rubbing with soap and talk about how long it takes to reach under the nails.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING.M_AG4_HW_BEFORE', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING', 'Washes only after eating and not before.', '{"question":"When must hands be washed?","wrong_answer":"After eating only","correct_answer":"Before eating and after using the toilet"}'::jsonb, 'The child washes to remove food, not germs.', 'Offer "After eating only" next to the right answer and ask the question again in a new context.', 'Ask what is on hands before a meal after playing outside.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES.M_AG4_HP_NAILS', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HYGIENE_PRACTICES', 'Thinks long nails are fine as long as the hands are washed.', '{"question":"Why should nails be kept short and clean?","wrong_answer":"They do not matter if hands are washed","correct_answer":"Dirt and germs hide under long nails"}'::jsonb, 'The child washes the palms and does not think about the space under the nails.', 'Offer "They do not matter if hands are washed" next to the right answer and ask the question again in a new context.', 'Use a toothpick (gently) to show the dirt under a long nail after gardening.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING.M_AG4_HW_TOWEL', 'AGRI.G4.HYGIEN.PERSONAL_HYGIENE.HAND_WASHING', 'Dries washed hands on dirty clothes or a shared dirty towel.', '{"question":"How should you dry your hands after washing?","wrong_answer":"On my dirty shirt","correct_answer":"In the air or on a clean towel of my own"}'::jsonb, 'The child thinks once hands are washed, they stay clean whatever they touch.', 'Offer "On my dirty shirt" next to the right answer and ask the question again in a new context.', 'Ask where the germs on the dirty shirt go when wet hands touch it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS.M_AG4_CLM_MIX', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS', 'Mixes up the ways of cleaning (sweeping a wet floor, mopping dust).', '{"question":"Which method removes dry dirt from a floor?","wrong_answer":"Mopping","correct_answer":"Sweeping"}'::jsonb, 'The child thinks every floor job is mopping.', 'Offer "Mopping" next to the right answer and ask the question again in a new context.', 'Try to sweep a muddy floor and mop a dusty one.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS.M_AG4_CLM_DUST', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS', 'Thinks dusting means sweeping the yard.', '{"question":"What is dusting?","wrong_answer":"Sweeping the compound outside","correct_answer":"Wiping dust off shelves and furniture"}'::jsonb, 'The child links dust with the ground.', 'Offer "Sweeping the compound outside" next to the right answer and ask the question again in a new context.', 'Wipe a table with a cloth and look at the dust on it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS.M_AG4_CLM_RUBBISH', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS', 'Throws rubbish anywhere or burns plastic.', '{"question":"Where should rubbish from the house go?","wrong_answer":"Anywhere outside, the wind will take it","correct_answer":"Into a bin or a rubbish pit"}'::jsonb, 'The child thinks outside is for dirt.', 'Offer "Anywhere outside, the wind will take it" next to the right answer and ask the question again in a new context.', 'Walk round the school and look at where rubbish piles up and what it attracts.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER.M_AG4_CO_FLOOR', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER', 'Sweeps the floor first and dusts the shelves after.', '{"question":"Which job comes first when cleaning a room?","wrong_answer":"Sweeping the floor","correct_answer":"Dusting the shelves"}'::jsonb, 'The child cleans from the dirtiest part.', 'Offer "Sweeping the floor" next to the right answer and ask the question again in a new context.', 'Dust a shelf over a swept floor and look at the floor again.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER.M_AG4_CO_MOP', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER', 'Mops before sweeping.', '{"question":"What comes first, sweeping or mopping?","wrong_answer":"Mopping, then sweeping","correct_answer":"Sweeping, then mopping"}'::jsonb, 'The child thinks water does all the work.', 'Offer "Mopping, then sweeping" next to the right answer and ask the question again in a new context.', 'Mop a dusty floor and see the mud it makes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER.M_AG4_CO_GREASY', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER', 'Washes the greasy sufuria first in the same water.', '{"question":"Which should be washed first?","wrong_answer":"The greasy sufuria","correct_answer":"The cups and plates"}'::jsonb, 'The child washes the dirtiest first.', 'Offer "The greasy sufuria" next to the right answer and ask the question again in a new context.', 'Wash a cup after a greasy pot in the same water and feel it.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS.M_AG4_CLM_WIPE', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_METHODS', 'Thinks wiping and scrubbing are the same job.', '{"question":"Which method suits a dirty cemented veranda?","wrong_answer":"Wiping with a dry cloth","correct_answer":"Scrubbing with a brush, soap and water"}'::jsonb, 'The child knows both use a cloth or brush and does not match the method to how dirty the surface is.', 'Offer "Wiping with a dry cloth" next to the right answer and ask the question again in a new context.', 'Try a dry cloth on a muddy floor tile, then a brush and soapy water.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER.M_AG4_CO_WINDOWS', 'AGRI.G4.HYGIEN.DOMESTIC_HYGIENE.CLEANING_ORDER', 'Opens no windows while sweeping, so dust stays in the room.', '{"question":"What should you do before sweeping a room?","wrong_answer":"Close the windows","correct_answer":"Open the windows and move the furniture"}'::jsonb, 'The child thinks closed windows keep the dust from blowing about.', 'Offer "Close the windows" next to the right answer and ask the question again in a new context.', 'Sweep a dusty corner with windows closed and open; watch where the dust goes.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS.M_AG4_PI_MATCH', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS', 'Matches the wrong protective item to the job (gloves for the eyes, a mask for the feet).', '{"question":"Which item protects the eyes?","wrong_answer":"Gloves","correct_answer":"Goggles"}'::jsonb, 'The child knows the items but not the body part each protects.', 'Offer "Gloves" next to the right answer and ask the question again in a new context.', 'Hold each item up and say which body part it covers.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS.M_AG4_PI_FASHION', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS', 'Thinks protective clothing is for looks.', '{"question":"Why does a farmer wear a face mask when spraying?","wrong_answer":"To look smart","correct_answer":"To keep the spray out of the nose and mouth"}'::jsonb, 'The child has seen the clothing but not its job.', 'Offer "To look smart" next to the right answer and ask the question again in a new context.', 'Ask what would happen to a farmer who breathes in the spray.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS.M_AG4_PI_SANDALS', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS', 'Thinks sandals protect the feet on the farm.', '{"question":"Which footwear protects a farmer in wet muddy ground?","wrong_answer":"Open sandals","correct_answer":"Gumboots"}'::jsonb, 'The child thinks any shoe will do.', 'Offer "Open sandals" next to the right answer and ask the question again in a new context.', 'Ask what can cut or bite a bare foot in a shamba.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE.M_AG4_PC_DIRTY', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE', 'Puts protective clothing away dirty.', '{"question":"What is done with a muddy apron after work?","wrong_answer":"Hang it away as it is","correct_answer":"Wash it with soap and water"}'::jsonb, 'The child thinks it will clean itself.', 'Offer "Hang it away as it is" next to the right answer and ask the question again in a new context.', 'Smell a stored muddy apron after a week.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE.M_AG4_PC_WET', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE', 'Stores gloves or boots while wet.', '{"question":"How should washed gloves be stored?","wrong_answer":"Packed away while still wet","correct_answer":"Dried fully, then kept in a clean dry place"}'::jsonb, 'The child is in a hurry to put things away.', 'Offer "Packed away while still wet" next to the right answer and ask the question again in a new context.', 'Pack away a damp cloth in a bag and smell it a week later.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE.M_AG4_PC_SHARE', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE', 'Shares a dirty mask or gloves with others.', '{"question":"Two children want to use the same dirty gloves. What is best?","wrong_answer":"Share them, gloves are gloves","correct_answer":"Wash them first, or each use a clean pair"}'::jsonb, 'The child thinks sharing is always kind.', 'Offer "Share them, gloves are gloves" next to the right answer and ask the question again in a new context.', 'Ask how germs and chemicals move from one hand to another.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS.M_AG4_PI_APRON', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_ITEMS', 'Thinks an apron is for keeping warm.', '{"question":"What does an apron protect?","wrong_answer":"It keeps the body warm","correct_answer":"It keeps clothes clean from food, dirt and splashes"}'::jsonb, 'The child sees an apron as an extra layer of clothing.', 'Offer "It keeps the body warm" next to the right answer and ask the question again in a new context.', 'Splash water on an apron worn over a shirt; the shirt stays dry.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE.M_AG4_PC_BOOTS', 'AGRI.G4.HYGIEN.CLEANING_PERSONAL_PROTEC.PPE_CARE', 'Washes only the outside of gumboots and leaves the inside wet and dirty.', '{"question":"How should gumboots be cleaned?","wrong_answer":"Wash the outside only","correct_answer":"Wash outside and inside, then dry them upside down"}'::jsonb, 'The child cleans what can be seen.', 'Offer "Wash the outside only" next to the right answer and ask the question again in a new context.', 'Feel inside a boot left wet; it smells and stays damp.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES.M_AG4_TT_PERM', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES', 'Thinks tacking is the final stitching and stays in the cloth.', '{"question":"What is tacking used for?","wrong_answer":"To join the cloth for good","correct_answer":"To hold the cloth together for a short time"}'::jsonb, 'The child sees a stitch and thinks it is the finished seam.', 'Offer "To join the cloth for good" next to the right answer and ask the question again in a new context.', 'Tack two pieces and sew them, then pull out the tacking.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES.M_AG4_TT_NAME', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES', 'Mixes up even, uneven and diagonal tacking.', '{"question":"Which tacking has long stitches on top and short stitches underneath?","wrong_answer":"Even tacking","correct_answer":"Uneven tacking"}'::jsonb, 'The child does not look at the length of the stitches.', 'Offer "Even tacking" next to the right answer and ask the question again in a new context.', 'Make each tacking on a scrap and compare the top and the back.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES.M_AG4_TT_SMALL', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES', 'Thinks tacking stitches are tiny and strong.', '{"question":"What are tacking stitches like?","wrong_answer":"Tiny and tight","correct_answer":"Long and loose"}'::jsonb, 'The child thinks all stitches are made to last.', 'Offer "Tiny and tight" next to the right answer and ask the question again in a new context.', 'Pull out a tacking stitch and then a back stitch and compare.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE.M_AG4_TU_KEEP', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE', 'Leaves the tacking in the finished garment.', '{"question":"What is done with the tacking when the sewing is finished?","wrong_answer":"It is left in the cloth","correct_answer":"It is pulled out"}'::jsonb, 'The child sees it as part of the stitching.', 'Offer "It is left in the cloth" next to the right answer and ask the question again in a new context.', 'Show a garment with tacking left in and ask what it looks like.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE.M_AG4_TU_ORDER', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE', 'Sews the final seam first and tacks after.', '{"question":"What comes first, tacking or the final stitching?","wrong_answer":"Final stitching, then tacking","correct_answer":"Tacking, then final stitching"}'::jsonb, 'The child does not know tacking is a guide.', 'Offer "Final stitching, then tacking" next to the right answer and ask the question again in a new context.', 'Sew two slippery pieces without tacking and see them slide.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE.M_AG4_TU_STRONG', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE', 'Tacks with tiny strong stitches in matching thread.', '{"question":"How should tacking be sewn?","wrong_answer":"With tiny, strong stitches","correct_answer":"With long, loose stitches in a thread that shows"}'::jsonb, 'The child thinks every stitch must be neat and strong.', 'Offer "With tiny, strong stitches" next to the right answer and ask the question again in a new context.', 'Compare how long it takes to unpick tiny stitches and long stitches.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES.M_AG4_TT_DIAG', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_TYPES', 'Thinks diagonal tacking is used to join a seam in a straight line.', '{"question":"What is diagonal tacking used for?","wrong_answer":"Joining a straight seam","correct_answer":"Holding layers of cloth flat together over a large area"}'::jsonb, 'The child thinks every tacking stitch is for seams.', 'Offer "Joining a straight seam" next to the right answer and ask the question again in a new context.', 'Show slanting stitches holding a lining flat; ask why they slope.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
INSERT INTO public.curriculum_misconceptions (code, skill_code, error, example, cause, reveals, help, status) VALUES ('AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE.M_AG4_TU_KNOT', 'AGRI.G4.PRODUC.MAKING_TACKING_STITCHES.TACK_USE', 'Ties a big knot at both ends so the tacking cannot come out.', '{"question":"How does tacking start and end?","wrong_answer":"With a big knot at each end","correct_answer":"With a small knot or a backstitch to start and a loose end so it pulls out easily"}'::jsonb, 'The child thinks every stitch must be fixed firmly.', 'Offer "With a big knot at each end" next to the right answer and ask the question again in a new context.', 'Pull out a tacking thread with and without knots at both ends.', 'draft') ON CONFLICT (code) DO UPDATE SET error = EXCLUDED.error, example = EXCLUDED.example, cause = EXCLUDED.cause, reveals = EXCLUDED.reveals, help = EXCLUDED.help, updated_at = now() WHERE public.curriculum_misconceptions.status = 'draft';
